<?php $page_title='Patients';require_once __DIR__.'/../includes/header.php';$q=trim($_GET['q']??'');$s=$pdo->prepare("SELECT * FROM patients WHERE name LIKE ? OR phone LIKE ? OR patient_code LIKE ? ORDER BY id DESC");$l="%$q%";$s->execute([$l,$l,$l]);$rows=$s->fetchAll();?>
