<div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Code</th><th>Name</th><th>Gender</th><th>Age</th><th>Phone</th><th>Blood Group</th><th></th></tr></thead><tbody><?php foreach($rows as $p):?><tr><td><?=$p['patient_code']?></td><td><?=e($p['name'])?></td><td><?=$p['gender']?></td><td><?=$p['age']?></td><td><?=$p['phone']?></td><td><?=$p['blood_group']?></td><td><a href="view.php?id=<?=$p['id']?>" class="btn btn-sm btn-outline-primary">View</a></td></tr><?php endforeach;?></tbody></table></div></div><?php require_once __DIR__.'/../includes/footer.php';?>